import type { Metadata } from "next";
import Link from "next/link";
import {
  Check,
  CreditCard,
  Megaphone,
  Users,
  X,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Tooltip } from "@/components/ui/tooltip";

export const metadata: Metadata = {
  title: "Admin — BJS Prep",
  description: "Platform overview for administrators.",
};

const pendingApprovals = [
  {
    id: "1",
    name: "Sadia Rahman",
    email: "sadia.rahman@example.com",
    university: "University of Dhaka",
    date: "2 days ago",
  },
  {
    id: "2",
    name: "Tanvir Ahmed",
    email: "tanvir.ahmed@example.com",
    university: "Jahangirnagar University",
    date: "3 days ago",
  },
  {
    id: "3",
    name: "Farhana Akter",
    email: "farhana.akter@example.com",
    university: "Chittagong University",
    date: "5 days ago",
  },
];

const recentRegistrations = [
  { id: "1", name: "Sadia Rahman", email: "sadia.rahman@example.com", tier: "University", verified: false, date: "25 Sep 2026" },
  { id: "2", name: "Tanvir Ahmed", email: "tanvir.ahmed@example.com", tier: "Other", verified: true, date: "24 Sep 2026" },
  { id: "3", name: "Farhana Akter", email: "farhana.akter@example.com", tier: "University", verified: true, date: "22 Sep 2026" },
  { id: "4", name: "Nabil Hossain", email: "nabil.hossain@example.com", tier: "Other", verified: true, date: "21 Sep 2026" },
  { id: "5", name: "Maliha Karim", email: "maliha.karim@example.com", tier: "University", verified: true, date: "20 Sep 2026" },
];

export default function AdminPage() {
  return (
    <div className="mx-auto max-w-6xl">
      <header className="flex flex-col gap-2 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="font-heading text-3xl font-bold text-primary lg:text-4xl">
            Overview
          </h1>
          <p className="mt-2 text-base text-muted">Platform at a glance.</p>
        </div>
        <Tooltip content="Available once students API is wired.">
          <button
            type="button"
            disabled
            className="h-10 w-fit rounded-md border border-border px-4 text-sm text-foreground opacity-60"
          >
            Export CSV
          </button>
        </Tooltip>
      </header>

      <section className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Total students" number="143" detail="+12 this week" />
        <StatCard label="University students" number="128" detail="89% of total" />
        <StatCard label="Other applicants" number="15" detail="11% of total" />
        <StatCard label="Verified accounts" number="131" detail="91% verified" />
      </section>

      <section className="mt-12">
        <div className="flex items-center justify-between">
          <h2 className="font-heading text-xl font-bold text-primary">
            Pending approvals
          </h2>
          <Link
            href="/admin/students?status=pending"
            className="text-sm text-accent hover:underline"
          >
            View all →
          </Link>
        </div>
        <Card className="mt-4 overflow-hidden border-border bg-card">
          {pendingApprovals.length > 0 ? (
            <>
              <div className="hidden grid-cols-12 gap-4 border-b border-border px-6 py-3 text-xs uppercase tracking-wide text-muted md:grid">
                <span className="col-span-4">Name</span>
                <span className="col-span-4">University</span>
                <span className="col-span-2">Date</span>
                <span className="col-span-2 text-right">Action</span>
              </div>
              {pendingApprovals.map((student) => (
                <div
                  key={student.id}
                  className="grid grid-cols-1 gap-3 border-b border-border px-6 py-4 last:border-b-0 md:grid-cols-12 md:items-center md:gap-4"
                >
                  <div className="md:col-span-4">
                    <p className="text-sm font-medium text-foreground">
                      {student.name}
                    </p>
                    <p className="text-xs text-muted">{student.email}</p>
                  </div>
                  <p className="text-sm text-foreground md:col-span-4">
                    {student.university}
                  </p>
                  <p className="text-xs text-muted md:col-span-2">
                    {student.date}
                  </p>
                  <div className="md:col-span-2 md:text-right">
                    <button
                      type="button"
                      className="h-8 rounded-md bg-primary px-3 text-xs text-cream hover:bg-primary-dark"
                    >
                      Approve
                    </button>
                  </div>
                </div>
              ))}
            </>
          ) : (
            <EmptyApprovals />
          )}
        </Card>
      </section>

      <section className="mt-12">
        <div className="flex items-center justify-between">
          <h2 className="font-heading text-xl font-bold text-primary">
            Recent registrations
          </h2>
          <Link
            href="/admin/students"
            className="text-sm text-accent hover:underline"
          >
            View all students →
          </Link>
        </div>
        <Card className="mt-4 overflow-hidden border-border bg-card">
          <div className="hidden grid-cols-12 gap-4 border-b border-border px-6 py-3 text-xs uppercase tracking-wide text-muted md:grid">
            <span className="col-span-4">Name</span>
            <span className="col-span-3">Tier</span>
            <span className="col-span-2">Verified</span>
            <span className="col-span-3 text-right">Date</span>
          </div>
          {recentRegistrations.map((student) => (
            <div
              key={student.id}
              className="grid grid-cols-1 gap-3 border-b border-border px-6 py-4 last:border-b-0 md:grid-cols-12 md:items-center md:gap-4"
            >
              <div className="md:col-span-4">
                <p className="text-sm font-medium text-foreground">
                  {student.name}
                </p>
                <p className="text-xs text-muted">{student.email}</p>
              </div>
              <div className="md:col-span-3">
                <Badge
                  className={
                    student.tier === "University"
                      ? "border-primary text-primary"
                      : "border-accent text-accent"
                  }
                >
                  {student.tier}
                </Badge>
              </div>
              <div className="md:col-span-2">
                {student.verified ? (
                  <Check className="text-accent" size={16} />
                ) : (
                  <X className="text-muted" size={16} />
                )}
              </div>
              <p className="text-xs text-muted md:col-span-3 md:text-right">
                {student.date}
              </p>
            </div>
          ))}
        </Card>
      </section>

      <section className="mt-12">
        <h2 className="font-heading text-xl font-bold text-primary">
          Quick actions
        </h2>
        <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          <QuickAction
            href="/admin/students"
            icon={<Users size={24} className="text-primary" />}
            title="Manage students"
            description="View, filter, and approve registrations."
          />
          <QuickAction
            href="/admin/notices"
            icon={<Megaphone size={24} className="text-primary" />}
            title="Post a notice"
            description="Publish announcements to all students."
            badge="Coming soon"
          />
          <QuickAction
            href="/admin/payments"
            icon={<CreditCard size={24} className="text-primary" />}
            title="Review payments"
            description="Track enrollments and revenue."
            badge="Coming soon"
          />
        </div>
      </section>
    </div>
  );
}

function StatCard({ label, number, detail }: { label: string; number: string; detail: string }) {
  return (
    <Card className="relative border-border bg-card p-4 sm:p-6">
      <span className="absolute left-6 top-0 h-1 w-10 rounded-b bg-accent" />
      <p className="text-xs uppercase tracking-wide text-muted">{label}</p>
      <p className="mt-2 font-heading text-4xl font-bold text-primary">{number}</p>
      <p className="mt-1 text-xs text-muted">{detail}</p>
    </Card>
  );
}

function EmptyApprovals() {
  return (
    <div className="py-12 text-center">
      <Users className="mx-auto text-muted" size={40} />
      <h3 className="mt-4 text-sm font-medium text-primary">
        No pending approvals.
      </h3>
      <p className="mt-1 text-xs text-muted">New registrations will appear here.</p>
    </div>
  );
}

function QuickAction({
  href,
  icon,
  title,
  description,
  badge,
}: {
  href: string;
  icon: React.ReactNode;
  title: string;
  description: string;
  badge?: string;
}) {
  return (
    <Link
      href={href}
      className="rounded-lg border border-border bg-card p-6 shadow-sm transition-shadow hover:shadow-md"
    >
      {icon}
      <h3 className="mt-4 text-base font-semibold text-primary">{title}</h3>
      <p className="mt-1 text-sm text-muted">{description}</p>
      {badge && (
        <Badge className="mt-3 border-border text-xs text-muted">{badge}</Badge>
      )}
    </Link>
  );
}
